import type { Metadata } from "next";
import Page from "@/components/deals-page/page";
import getCities from "@/services/tour-category-pages/getCities";

export const dynamic = "force-static";
export const metadata: Metadata = {
  title:
    "Best Tour Package Offers and Get Deals 2026/2027 - TravelShop Booking",
  description:
    "Discover the best tour package offers and get unbeatable trip deals for 2026/2027 on TravelShop Booking website.",
};

export default async function Home() {
  const cities = await getCities(0);

  return (
    <Page
      params={{
        cities: cities.data.map((item: any) => ({
          pageTitle: item.breadcrumbTitle,
          pageUrl: `/${item.pageUrl}`,
          locationId: item.paramLocationId,
        })),
      }}
    />
  );
}
